style.css:
@-moz-document domain("drive.google.com") {
html, body {
    background: url('https://staticg.sportskeeda.com/editor/2024/05/5dbc5-17159017650761-1920.jpg?w=640') no-repeat center center fixed !important;
    background-size: cover !important;
    font-family: 'Segoe UI', sans-serif !important;
    color: white !important;
  }

  /* Optional: translucent overlay for readability */
  body::before {
    content: "";
    position: fixed;
    top: 0; left: 0;
    width: 100vw; height: 100vh;
    background: rgba(0, 0, 0, 0.5); /* dark overlay */
    z-index: -1;
  }

  /* Sidebar and buttons background (optional) */
  .a-D-Pc-Ab,
  .a-D-Pc-Zd,
  .a-D-Pc,
  .a-v-T,
  .a-D-yc {
    background-color: rgba(0, 0, 0, 0.3) !important;
    backdrop-filter: blur(5px);
    color: white !important;
  }

  /* File text color fix */
  .a-D-gb, .a-D-T {
    color: #ffffff !important;
    text-shadow: 0 0 5px #000000aa;
  }

  /* Optional hover effect for files/folders */
  .a-D-mc:hover {
    background-color: rgba(255, 255, 255, 0.1) !important;
  }
}
